const fs = require('fs');
const path = require('path');
let inp = {};
try { inp = $('Webhook Trigger').first().json.body || {}; } catch (e) { inp = {}; }
const jobId = (inp.jobId || '').toString().trim();
const product = (inp.product || inp.name || 'Site').toString().trim() || 'Site';
const ptype = (inp.productType || 'tool').toString().toLowerCase();
const siteUrl = (inp.siteUrl || inp.url || '').toString().trim() || '（未提供）';
function slugify(t){ return (t||'').toLowerCase().trim().replace(/['"]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80)||'site'; }
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function fnum(v){ if(v===null||v===undefined||v==='') return null; const n=parseFloat(v); return isNaN(n)?null:n; }
function mean(a){ const v=a.filter(x=>x!==null&&x!==undefined&&x!==''); return v.length? v.reduce((s,x)=>s+Number(x),0)/v.length : null; }
const slug = slugify(product);

// ---- 指标归一化 ----
let raw = inp.metrics;
if (typeof raw === 'string' && raw.trim()) { try { raw = JSON.parse(raw); } catch(e){ raw = null; } }
let points = [];
if (Array.isArray(raw)) {
  points = raw.map((it,i) => ({
    date: String(it.date || it.day || ('T'+(i+1))),
    uv: fnum(it.uv), pv: fnum(it.pv || it.pageviews),
    avgPages: fnum(it.avgPages || it.pagesPerUser),
    bounce: fnum(it.bounce || it.bounceRate),
    rankings: (it.rankings && typeof it.rankings === 'object') ? it.rankings : {},
  }));
} else if (raw && typeof raw === 'object') {
  const dates = raw.dates || raw.date || [];
  const n = Math.max((raw.uv||[]).length||0, (raw.pv||[]).length||0, dates.length||0);
  for (let i=0;i<n;i++){
    points.push({ date: String(dates[i]||('T'+(i+1))), uv: fnum((raw.uv||[])[i]), pv: fnum((raw.pv||[])[i]),
      avgPages: fnum((raw.avgPages||[])[i]), bounce: fnum((raw.bounce||[])[i]),
      rankings: (raw.rankings && raw.rankings[String(dates[i])]) || {} });
  }
}
points = points.filter(p => p.uv!==null || p.pv!==null || p.avgPages!==null || p.bounce!==null || Object.keys(p.rankings).length).slice(0,60);

// ---- R20 指标分析 ----
let metrics = {};
if (!points.length) {
  metrics = { hasData:false, summary:{uvTotal:0,pvTotal:0,avgPages:null,bounce:null},
    trend:{uv:null,pv:null,direction:'数据不足'}, rankings:{keywords:[],avgPosition:null,up:[],down:[]},
    alerts:['未提供任何指标数据——粘贴 GSC/Analytics 导出的 JSON 后可生成趋势与告警。'], health:null };
} else {
  const uvTotal = points.reduce((s,p)=>s+(p.uv||0),0);
  const pvTotal = points.reduce((s,p)=>s+(p.pv||0),0);
  let avgPages = mean(points.map(p=>p.avgPages));
  if (avgPages===null && uvTotal>0) avgPages = pvTotal/uvTotal;
  let bounce = mean(points.map(p=>p.bounce));
  if (bounce!==null && bounce>1) bounce = bounce/100;
  const half = Math.max(1, Math.floor(points.length/2));
  const uvUp = mean(points.slice(half).map(p=>p.uv))||0, uvBase = mean(points.slice(0,half).map(p=>p.uv))||0;
  const pvUp = mean(points.slice(half).map(p=>p.pv))||0, pvBase = mean(points.slice(0,half).map(p=>p.pv))||0;
  const uvDelta = uvBase? (uvUp-uvBase)/uvBase*100 : null;
  const pvDelta = pvBase? (pvUp-pvBase)/pvBase*100 : null;
  const direction = uvDelta===null?'持平':uvDelta>8?'上升':uvDelta<-8?'下降':'持平';
  const firstRk = points[0].rankings||{}, lastRk = points[points.length-1].rankings||{};
  const kws = Array.from(new Set([...Object.keys(firstRk), ...Object.keys(lastRk)]));
  const kwRows = kws.map(k=>{ const a=fnum(firstRk[k]), b=fnum(lastRk[k]);
    return {keyword:k, from:a, to:b, change:(a!==null&&b!==null)?(a-b):null}; });
  const up = kwRows.filter(r=>(r.change||0)>0).map(r=>r.keyword).slice(0,8);
  const down = kwRows.filter(r=>(r.change||0)<0).map(r=>r.keyword).slice(0,8);
  const avgPos = mean(kwRows.map(r=>r.to));
  const alerts = [];
  if (bounce!==null && bounce>0.65) alerts.push('跳出率偏高（'+Math.round(bounce*100)+'%）：落地页首屏与搜索意图可能不匹配，建议优化标题/首屏/内链。');
  if (avgPages!==null && avgPages<1.5) alerts.push('人均页数偏低（'+avgPages.toFixed(1)+'）：站内内链与相关内容推荐不足。');
  if (uvDelta!==null && uvDelta<-20) alerts.push('UV 环比下降 '+Math.abs(uvDelta).toFixed(0)+'%：排查排名波动与外链增长停滞（R21）。');
  if (kwRows.some(r=>(r.change||0)<=-3)) alerts.push('关键词排名下滑 ≥3 位：'+kwRows.filter(r=>(r.change||0)<=-3).map(r=>r.keyword).slice(0,5).join('、')+'——优先补内容/外链。');
  if (avgPos!==null && avgPos>20) alerts.push('平均排名 '+avgPos.toFixed(1)+'（>20）：核心词在第二页外，建议长尾内容（R13）+ 外链（R21）。');
  if (!alerts.length) alerts.push('暂无告警：指标处于健康区间，保持节奏并继续回流档案。');
  let score = 100;
  if (bounce!==null) score -= Math.min(25, Math.max(0, Math.round((bounce-0.4)*60)));
  if (avgPages!==null) score -= Math.min(20, Math.max(0, Math.round((3.0-avgPages)*10)));
  if (uvDelta!==null) score -= Math.min(25, Math.max(0, Math.round(-uvDelta/2)));
  if (avgPos!==null) score -= Math.min(20, Math.max(0, Math.round((avgPos-8)/2)));
  score = Math.max(5, Math.min(100, score));
  metrics = { hasData:true,
    summary:{uvTotal:uvTotal, pvTotal:pvTotal, avgPages:avgPages!==null?Math.round(avgPages*100)/100:null,
      bounce:bounce!==null?Math.round(bounce*1000)/1000:null, points:points.length},
    trend:{uv:uvDelta!==null?Math.round(uvDelta*10)/10:null, pv:pvDelta!==null?Math.round(pvDelta*10)/10:null, direction:direction},
    rankings:{keywords:kwRows, avgPosition:avgPos!==null?Math.round(avgPos*10)/10:null, up:up, down:down},
    alerts:alerts, health:score };
}

// ---- R25 档案回流 ----
const SITES = '/home/node/sites';
function classify(d){
  const st = String(d.status||''), pl = d.plan||{};
  if (st.includes('monitor')) return 'monitor';
  if (st.includes('monetize') || pl.tiers) return 'monetize';
  if (st.includes('backlink') || pl.anchorPlan) return 'backlink';
  if (st.includes('content') || d.pages) return 'content';
  if (st.includes('research') || (pl.keywords && !pl.anchorPlan)) return 'research';
  if (st.includes('seo')) return 'seo';
  if (st.includes('deploy') || st.includes('部署') || d.url !== undefined || ('slug' in d && 'url' in d)) return 'deploy';
  return 'other';
}
const jobs = []; const jobCounts = {};
try {
  const cbDir = path.join(SITES, '_bridge_cb');
  if (fs.existsSync(cbDir)) {
    for (const f of fs.readdirSync(cbDir).filter(x=>x.endsWith('.json')).sort()) {
      try {
        const d = JSON.parse(fs.readFileSync(path.join(cbDir,f),'utf-8'));
        const cat = classify(d);
        jobCounts[cat] = (jobCounts[cat]||0)+1;
        jobs.push({jobId:d.jobId||f.replace('.json',''), category:cat, status:d.status, files:d.files||[]});
      } catch(e){}
    }
  }
} catch(e){}
const assets = {contentPages:0, contentSites:[], monetizePlans:[], backlinkPlans:[]};
try {
  const cd = path.join(SITES,'_content');
  if (fs.existsSync(cd)) for (const d of fs.readdirSync(cd)) {
    const dir = path.join(cd,d); if (!fs.statSync(dir).isDirectory()) continue;
    const pages = fs.readdirSync(dir).filter(x=>x.endsWith('.html')).length;
    assets.contentPages += pages; assets.contentSites.push({slug:d, pages:pages});
  }
  const md = path.join(SITES,'_monetize');
  if (fs.existsSync(md)) for (const d of fs.readdirSync(md)) {
    const pf = path.join(md,d,'plan.json');
    if (fs.existsSync(pf)) { try { const p = JSON.parse(fs.readFileSync(pf,'utf-8'));
      assets.monetizePlans.push({slug:d, winner:(p.comparison||{}).winner, tiers:(p.tiers||[]).length}); } catch(e){} }
  }
  const bd = path.join(SITES,'_backlink');
  if (fs.existsSync(bd)) for (const d of fs.readdirSync(bd)) {
    const pf = path.join(bd,d,'plan.json');
    if (fs.existsSync(pf)) { try { const p = JSON.parse(fs.readFileSync(pf,'utf-8'));
      assets.backlinkPlans.push({slug:d, channels:(p.channels||[]).length, anchors:(p.anchorPlan||[]).length}); } catch(e){} }
  }
} catch(e){}
const archive = {jobs:jobs.slice(-40), jobCounts:jobCounts, assets:assets, totalCallbacks:jobs.length};

// ---- 优化建议 ----
const suggestions = [];
if (!jobCounts.research) suggestions.push({priority:'P0', action:'跑 R1 需求调研（keyword-research）', why:'档案中没有调研记录——先选对词再做页是内链策略第一步。', target:'/research'});
if (!assets.contentPages) suggestions.push({priority:'P0', action:'跑 R13 程序化内容生产（content-gen）', why:'站点还没有 SEO 落地页资产，外链与排名无落点。', target:'/content'});
else if (assets.contentPages < 10) suggestions.push({priority:'P1', action:'扩充 R13 内容页到 10+（长尾词矩阵）', why:'当前 '+assets.contentPages+' 页，长尾覆盖不足。', target:'/content'});
if (!assets.monetizePlans.length) suggestions.push({priority:'P1', action:'跑 R24 变现设计（/monetize）', why:'缺定价与变现模型，流量来了无法转化收入。', target:'/monetize'});
if (!assets.backlinkPlans.length) suggestions.push({priority:'P1', action:'跑 R21/R22 外链推广（/backlink）', why:'站外为零——站外比站内更重要。', target:'/backlink'});
if (!metrics.hasData) suggestions.push({priority:'P1', action:'接入指标数据（GSC/Analytics 导出 JSON）', why:'没有 UV/PV/排名时序，监控与告警无法生效。', target:'/monitor'});
else {
  if (metrics.trend.direction === '下降') suggestions.push({priority:'P0', action:'排查流量下降：排名波动页 + 外链增速', why:'UV 环比下降 '+(metrics.trend.uv||0)+'%。', target:'/monitor'});
  if (metrics.rankings.down.length) suggestions.push({priority:'P1', action:'针对下滑关键词补内容 + 部分匹配外链', why:'下滑词：'+metrics.rankings.down.slice(0,5).join('、'), target:'/backlink'});
}
suggestions.push({priority:'P2', action:'每月回跑本引擎（/monitor）沉淀档案', why:'档案越厚，建议越准；监控是闭环起点也是终点。', target:'/monitor'});

// ---- 报告 ----
const L = [];
L.push('监控与数据闭环报告（R20/R25）');
L.push('================================================');
L.push('产品：'+product+' ｜ 类型：'+ptype+' ｜ 站点：'+siteUrl);
L.push('');
L.push('【一、流量与体验指标（R20）】');
if (!metrics.hasData) L.push('  暂无指标数据——粘贴 GSC/Analytics 导出的 JSON 后可生成趋势、排名与告警。');
else {
  const s = metrics.summary;
  L.push('  采样点 : '+s.points+' 个 ｜ UV 合计 : '+s.uvTotal.toLocaleString('en-US')+' ｜ PV 合计 : '+s.pvTotal.toLocaleString('en-US'));
  L.push('  人均页数 : '+s.avgPages+' ｜ 跳出率 : '+(s.bounce!==null?Math.round(s.bounce*100)+'%':'—'));
}
L.push('');
L.push('【二、趋势分析】');
if (metrics.trend.uv===null) L.push('  数据不足，无法计算趋势。');
else L.push('  UV 环比 : '+(metrics.trend.uv>0?'+':'')+metrics.trend.uv+'% ｜ PV 环比 : '+(metrics.trend.pv||0)+'% ｜ 方向 : '+metrics.trend.direction);
L.push('');
L.push('【三、排名动态】');
if (!metrics.rankings.keywords.length) L.push('  暂无排名数据（在指标 JSON 的 rankings 里填 {关键词: 排名}）。');
else {
  L.push('  跟踪词 : '+metrics.rankings.keywords.length+' 个 ｜ 平均排名 : '+metrics.rankings.avgPosition);
  if (metrics.rankings.up.length) L.push('  上升 : '+metrics.rankings.up.join('、'));
  if (metrics.rankings.down.length) L.push('  下降 : '+metrics.rankings.down.join('、'));
}
L.push('');
L.push('【四、健康分与告警】');
L.push('  健康分 : '+(metrics.health===null?'—':metrics.health+' / 100'));
metrics.alerts.forEach(a => L.push('  ⚠ '+a));
L.push('');
L.push('【五、站点档案回流（R25）】');
const counts = Object.keys(jobCounts).sort().map(k=>k+'×'+jobCounts[k]).join('、') || '（空）';
L.push('  回调历史 : '+archive.totalCallbacks+' 条 ｜ 分类 : '+counts);
L.push('  内容页 : '+assets.contentPages+' 页 ｜ 变现方案 : '+assets.monetizePlans.length+' 份 ｜ 外链方案 : '+assets.backlinkPlans.length+' 份');
L.push('  档案已沉淀 → sites/_archive/'+slug+'/profile.json');
L.push('');
L.push('【六、下一轮优化建议（闭环输出）】');
suggestions.forEach((s,i)=>{ L.push('  '+(i+1)+'. ['+s.priority+'] '+s.action); L.push('     依据 : '+s.why); });
L.push('');
L.push('【七、闭环路径】');
L.push('  监控(R20) → 档案沉淀(R25) → 优化建议 → 回到调研(R1)/内容(R13)/外链(R21)/变现(R24) → 再监控。');
L.push('');
L.push('说明：monitor.html 为带 SVG 趋势图的监控看板，profile.json 为站点档案，均已落盘。');
const report = L.join('\n');

// ---- monitor.html（SVG 趋势图） ----
let svg = '<p class="empty">暂无时序数据。</p>';
if (points.length) {
  const W=680,H=220,PAD=36,n=points.length;
  const uvV=points.map(p=>p.uv||0), pvV=points.map(p=>p.pv||0);
  const vmax=Math.max(...uvV,...pvV,1);
  const xy = vals => vals.map((v,i)=>{
    const step=(W-PAD*2)/Math.max(1,n-1);
    return (PAD+i*step).toFixed(1)+','+(H-PAD-(v/vmax)*(H-PAD*2)).toFixed(1);
  }).join(' ');
  let grid='';
  for(let y=PAD;y<=H-PAD;y+=(H-PAD*2)/4){ grid+='<line x1="'+PAD+'" y1="'+y+'" x2="'+(W-PAD)+'" y2="'+y+'" stroke="rgba(23, 19, 27, .10)"/>'; }
  let labels='';
  points.forEach((p,i)=>{
    if (n<=12 || i%Math.max(1,Math.floor(n/10))===0) {
      const step=(W-PAD*2)/Math.max(1,n-1);
      labels+='<text x="'+(PAD+i*step).toFixed(1)+'" y="'+(H-12)+'" font-size="10" fill="#566074" text-anchor="middle">'+esc(String(p.date).slice(-5))+'</text>';
    }
  });
  svg = '<svg viewBox="0 0 '+W+' '+H+'" width="100%" style="max-width:'+W+'px;display:block;margin:0 auto">'+grid+
    '<polyline fill="none" stroke="#5b34e6" stroke-width="2.5" points="'+xy(uvV)+'"/>'+
    '<polyline fill="none" stroke="#5b34e6" stroke-width="2.5" stroke-dasharray="6 4" points="'+xy(pvV)+'"/>'+labels+'</svg>'+
    '<div class="legend"><span class="k uv"></span>UV <span class="k pv"></span>PV</div>';
}
const rkRows = metrics.rankings.keywords.slice(0,12).map(r =>
  '<tr><td>'+esc(r.keyword)+'</td><td>'+(r.from===null?'—':r.from)+'</td><td>'+(r.to===null?'—':r.to)+'</td><td>'+
  (r.change===null?'—':(r.change>0?'+':'')+Math.round(r.change))+'</td></tr>').join('');
const alertItems = metrics.alerts.map(a=>'<li>'+esc(a)+'</li>').join('');
const sugItems = suggestions.map(s=>'<li class="sug"><span class="pri">'+esc(s.priority)+'</span><div><strong>'+esc(s.action)+'</strong><div class="why">'+esc(s.why)+'</div></div></li>').join('');
const health = metrics.health;
const healthHtml = health===null ? '<div class="health">—<span>健康分</span></div>'
  : '<div class="health">'+health+'<span>健康分</span></div>';
const html = '<!doctype html>\n<html lang="zh">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>'+esc(product)+' · 监控看板</title>\n<style>\n:root{--accent:#5b34e6;--gold:#5b34e6;--ink:#17131b;--muted:#566074;--line:rgba(23, 19, 27, .12);--surface:#fbfcfe}\n*{box-sizing:border-box}\nbody{margin:0;font-family:"Plus Jakarta Sans","PingFang SC","Microsoft YaHei",sans-serif;color:var(--ink);background:#fffdf9;padding:40px 18px}\n.wrap{max-width:920px;margin:0 auto}\nh1{font-family:"Fraunces",Georgia,serif;font-size:30px;margin:0 0 6px}\n.sub{color:var(--muted);margin:0 0 24px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:22px;margin:0 0 16px;position:relative}\n.card h2{margin:0 0 12px;font-size:17px;color:var(--accent)}\n.health{float:right;font-family:"Fraunces",Georgia,serif;font-size:40px;font-weight:700;line-height:1;color:var(--accent)}\n.health span{display:block;font-family:var(--font-body);font-size:11px;font-weight:600;color:var(--muted);letter-spacing:.12em}\n.legend{text-align:center;font-size:12px;color:var(--muted);margin-top:6px}\n.legend .k{display:inline-block;width:14px;height:3px;margin:0 6px 0 12px;border-radius:2px;vertical-align:middle}\n.legend .k.uv{background:var(--accent)} .legend .k.pv{background:var(--gold)}\ntable{width:100%;border-collapse:collapse;font-size:13px}\nth,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--line)}\nth{color:var(--muted);font-weight:600}\nul{margin:0;padding-left:18px;line-height:1.85;font-size:13.5px}\n.sugs{list-style:none;padding:0}\n.sug{display:flex;gap:10px;padding:10px 0;border-bottom:1px solid var(--line)}\n.pri{flex:none;height:24px;min-width:30px;display:flex;align-items:center;justify-content:center;background:var(--accent);color:#fff;border-radius:8px;font-size:11px;font-weight:700}\n.why{color:var(--muted);font-size:12px;margin-top:2px;line-height:1.55}\n.empty{color:var(--muted);font-size:13px}\n</style>\n</head>\n<body>\n<div class="wrap">\n<h1>'+esc(product)+' · 监控看板</h1>\n<p class="sub">R20 长期数据监控 + R25 数据闭环回流（由监控引擎生成）</p>\n<section class="card">'+healthHtml+'<h2>一、流量趋势</h2>'+svg+'</section>\n<section class="card"><h2>二、排名动态</h2>'+(rkRows?'<table><thead><tr><th>关键词</th><th>起点</th><th>最新</th><th>变化</th></tr></thead><tbody>'+rkRows+'</tbody></table>':'<p class="empty">暂无排名数据。</p>')+'</section>\n<section class="card"><h2>三、告警</h2><ul>'+alertItems+'</ul></section>\n<section class="card"><h2>四、站点档案回流（R25）</h2><p class="empty">回调历史分类：'+esc(counts)+' ｜ 内容页 '+assets.contentPages+' · 变现方案 '+assets.monetizePlans.length+' · 外链方案 '+assets.backlinkPlans.length+'</p></section>\n<section class="card"><h2>五、下一轮优化建议</h2><ul class="sugs">'+sugItems+'</ul></section>\n</div>\n</body>\n</html>';

// ---- 落盘 ----
let files = [];
try {
  const outDir = path.join(SITES, '_monitor', slug);
  fs.mkdirSync(outDir, {recursive:true});
  fs.writeFileSync(path.join(outDir,'monitor.html'), html);
  const plan = {generated_at:new Date().toISOString(), product:product, health:metrics.health,
    metrics:metrics, archive:archive, suggestions:suggestions};
  fs.writeFileSync(path.join(outDir,'plan.json'), JSON.stringify(plan, null, 2));
  // 档案
  const arDir = path.join(SITES, '_archive', slug);
  fs.mkdirSync(arDir, {recursive:true});
  let history = [];
  try { const old = JSON.parse(fs.readFileSync(path.join(arDir,'profile.json'),'utf-8')); history = old.history||[]; } catch(e){}
  history.push({at:new Date().toISOString(), health:metrics.health, uv:metrics.summary.uvTotal, direction:metrics.trend.direction});
  const profile = {product:product, productType:ptype, siteUrl:siteUrl, updated_at:new Date().toISOString(),
    jobCounts:jobCounts, totalCallbacks:archive.totalCallbacks, assets:assets,
    metrics:metrics.summary, health:metrics.health, alerts:metrics.alerts, suggestions:suggestions,
    history:history.slice(-24)};
  fs.writeFileSync(path.join(arDir,'profile.json'), JSON.stringify(profile, null, 2));
  files = ['_monitor/'+slug+'/monitor.html', '_monitor/'+slug+'/plan.json', '_archive/'+slug+'/profile.json'];
} catch(e){ /* 路径不可写时忽略 */ }

return [{ json: { report: report, plan: { health:metrics.health, summary:metrics.summary, trend:metrics.trend,
  rankings:metrics.rankings, alerts:metrics.alerts, suggestions:suggestions,
  archive:{jobCounts:jobCounts, totalCallbacks:archive.totalCallbacks,
    assets:{contentPages:assets.contentPages, monetizePlans:assets.monetizePlans.length, backlinkPlans:assets.backlinkPlans.length}} },
  files: files } }];

const fs = require('fs');
let inp = {};
try { inp = $('Webhook Trigger').first().json.body || {}; } catch (e) { inp = {}; }
const jobId = (inp.jobId || '').toString();
let report = ''; try { report = ($('Code: Generate').first().json.report) || ''; } catch (e) {}
let plan = {}; try { plan = ($('Code: Generate').first().json.plan) || {}; } catch (e) {}
let files = []; try { files = ($('Code: Generate').first().json.files) || []; } catch (e) {}
const payload = {
  jobId: jobId, slug: '', url: '', dns: '',
  status: report ? 'monitor-done' : 'monitor-partial',
  result: report, plan: plan, files: files,
  log: report ? '监控报告与档案回流已完成' : '流程已触发，但报告内容暂未生成'
};
try {
  const dir = '/home/node/sites/_bridge_cb';
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(dir + '/' + (jobId || 'unknown') + '.json', JSON.stringify(payload, null, 2));
} catch (e) { /* 忽略 */ }
return [{ json: { ok: true, jobId: jobId } }];
